import{z as m,x as B,o as l,c as d,q as E,j as s,D as t,d as r,s as i,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"局部搜索与最大割","description":"","frontmatter":{"title":"局部搜索与最大割","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/local-search-max-cut.md","filePath":"cs/local-search-max-cut.md","lastUpdated":1791413859000}'),A={name:"cs/local-search-max-cut.md"};function p(h,a,c,u,D,C){const o=B("Mermaid");return l(),d("div",null,[a[2]||(a[2]=E('<h1 id="局部搜索与最大割" tabindex="-1">局部搜索与最大割 <a class="header-anchor" href="#局部搜索与最大割" aria-label="Permalink to &quot;局部搜索与最大割&quot;">​</a></h1><div class="epigraph"><p>翻转一个顶点若能增加割边则翻，局部最优至少一半边；Goemans–Williamson SDP 到 $0.878$。</p><footer>—— 据 Sahni and Gonzalez；Goemans and Williamson, Improved Approximation Algorithms for Maximum Cut, 1995；CLRS 第 35 章整理</footer></div><p>上一课<a href="/cs/knapsack-fptas">背包 FPTAS</a>用缩放 DP 换近似。最大割 NP 难，开头却便宜得惊人：随便切一刀再局部翻修就是 2-近似。缺口是这条局部搜索路线——为什么没人能再赚的划分至少切中一半边——以及 SDP 点名。不重写 LP 舍入框架；后课模拟退火加热。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把顶点划成 \\(S\\cup T\\)，割边是横跨两侧的边，目标最大化割边数。翻转顶点 \\(v\\) 的增益是新增跨边减去失去的：若 \\(v\\) 的内部邻居多于跨侧邻居，翻它必赚。没有翻转能赚时算法停下，此时每个顶点的跨侧邻居 \\(\\ge\\) 内部邻居；对顶点求和，每条边都在两个端点的账上各计一次，得 \\(2\\cdot\\mathrm{ALG}\\ge 2(m-\\mathrm{ALG})\\)，即 \\(\\mathrm{ALG}\\ge m/2\\ge\\mathrm{OPT}/2\\)——无权无向情形的 2-近似。加权版同样成立，计数换求和即可。</p><p>GW：半定松弛 + 随机超平面舍入，\\(0.878\\)。本课认结论，不写 SDP 求解。</p><p>缺口是翻转，不是 Karger（那是最小割）。</p><h3 id="局部最优不是全局" tabindex="-1">局部最优不是全局 <a class="header-anchor" href="#局部最优不是全局" aria-label="Permalink to &quot;局部最优不是全局&quot;">​</a></h3><p>局部最优可能离全局很远，\\(1/2\\) 这条保证是紧的——存在实例任何单点翻转都无增益、割却只有约一半；要超越得换松弛（SDP 或其它）。终止性也别想当然：每次增益至少 \\(1\\)（如整数权）时，总增益以 \\(m\\) 为上界、翻转才多项式步终止；实数权可能翻个不停。</p><p><span class="marginnote">Goemans–Williamson 1995。局部搜索 2-近似是教材。后课模拟退火逃局部最优，无最坏比保证。</span></p><p><span class="marginnote">初学者容易以为「一个顶点都翻不动了 = 切得很好」。实际上存在这样的图：每个单点翻转都不赚，割值却只有一半左右——\\(1/2\\) 是最坏情况的硬下限，不是典型表现。想突破这个天花板只能换武器（如 SDP），在原地多重启没用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从任意划分起步，循环扫描顶点，增益为正就翻，直到一整轮无翻转发生。随机初始化、多起点重启只在常数上捡便宜，不改最坏比。</p>',13)),(l(),s(n,null,{default:t(()=>[i(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20CUT%5B%22%E5%88%92%E5%88%86%22%5D%20--%3E%20FLIP%5B%22%E6%9C%89%E5%A2%9E%E7%9B%8A%E5%88%99%E7%BF%BB%E8%BD%AC%22%5D%0A%20%20FLIP%20--%3E%20LOC%5B%22%E5%B1%80%E9%83%A8%E6%9C%80%E4%BC%98%20%E2%89%A5%20m%2F2%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"加权时先看权的量级：整数权天然保证终止；浮点权要设阈值，阈值又可能吃掉近似比。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"数字实例：设顶点 \\(v\\) 有 3 条边连着自己一侧、1 条边跨侧。翻转后原来 3 条内部边变跨边、1 条跨边变内部，增益 \\(=3-1=2\\gt 0\\)，翻它必赚。算法就是把这个小账本对每个顶点算一遍，有赚就翻。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"\\(1/2\\) 这条保证从哪里来？证明是一条四步流水线：局部最优性给出每个顶点的不等式，求和把它抬成全局下界。",-1)),(l(),s(n,null,{default:t(()=>[i(o,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOC%5B%22%E5%B1%80%E9%83%A8%E6%9C%80%E4%BC%98%EF%BC%9A%E6%AF%8F%E7%82%B9%E8%B7%A8%E4%BE%A7%E9%82%BB%E5%B1%85%20%E2%89%A5%20%E5%86%85%E9%83%A8%E9%82%BB%E5%B1%85%22%5D%20--%3E%20INEQ%5B%22%E6%AF%8F%E4%B8%AA%E9%A1%B6%E7%82%B9%E5%86%99%E4%B8%80%E6%9D%A1%E4%B8%8D%E7%AD%89%E5%BC%8F%22%5D%0A%20%20INEQ%20--%3E%20SUM%5B%22%E5%AF%B9%E5%85%A8%E9%83%A8%E9%A1%B6%E7%82%B9%E6%B1%82%E5%92%8C%22%5D%0A%20%20SUM%20--%3E%20DBL%5B%22%E6%AF%8F%E6%9D%A1%E8%BE%B9%E5%9C%A8%E4%B8%A4%E7%AB%AF%E7%82%B9%E8%B4%A6%E4%B8%8A%E5%90%84%E8%AE%A1%E4%B8%80%E6%AC%A1%22%5D%0A%20%20DBL%20--%3E%20HALF%5B%22%E5%BE%97%202%C2%B7%E5%89%B2%E8%BE%B9%E6%95%B0%20%E2%89%A5%20m%EF%BC%8C%E5%8D%B3%E5%89%B2%E5%80%BC%20%E2%89%A5%20m%2F2%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=E('<p>证明的形状值得记住：局部最优性按点给出不等式，握手求和把它抬成全局下界，\\(1/2\\) 从割边与非割边的对称计数里掉出来。此形状在局部搜索证明里常见。与最大流最小割区分：名字像、目标相反——最小割求切断代价最小的一刀，最大割求跨越最多的一刀，前者的多项式算法帮不上后者。GW 的 \\(0.878\\) 来自几何舍入：顶点嵌入单位球面，随机超平面切两半，一条边被割中的概率随两端点夹角增大，期望割值 \\(\\ge 0.878\\cdot\\mathrm{OPT}\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 \\(0.878\\)，不进入 Unique Games 最优性讨论；最大有向割不写（常数不同）。后课默认：Max-Cut 局部搜索基线 \\(1/2\\)，SDP 更好。下一课模拟退火。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>翻转局部最优 \\(\\ge m/2\\)。</li><li>整数增益则多项式终止。</li><li>SDP \\(0.878\\) 点名。</li><li>出处：Goemans and Williamson, 1995；CLRS。</li></ul>',5))])}const S=m(A,[["render",p]]);export{f as __pageData,S as default};
